  /// FontAwesome to FUI (string names) mapping
  static const Map<String, String> _fuiMap = {
    'arrow-down': 'arrow-down',
    'arrow-left': 'arrow-left',
    'arrow-right': 'arrow-right',
    'arrow-up': 'arrow-up',
    'bar-chart': 'bar-chart-2',
    'bell': 'bell',
    'bookmark': 'bookmark',
