    'settings': 'settings',
    'share': 'share-2',
    'shopping-cart': 'shopping-cart',
    'star': 'star',
    'tag': 'tag',
    'trash': 'trash-2',
    'unlock': 'unlock',
    'upload': 'upload',
    'user': 'user',
    'x': 'x',
  };

  /// Convert icon string to appropriate Flutter icon
  ///
  /// Supported formats:
  /// - FontAwesome: "fa fa-home", "fas fa-user", "far fa-heart"
  /// - Flaticon Regular: "fi fi-rr-phone-call"
  /// - Flaticon Bold: "fi fi-sc-home"
  /// - Flaticon Straight: "fi fi-sr-user"
  static IconResult convert(
    String iconString, {
    IconType? preferredType,
    IconData fallback = Icons.help_outline,
  }) {
    if (iconString.isEmpty) {
      return IconResult(
        type: IconType.material,
        data: fallback,
        originalName: iconString,
      );
    }

    final parsed = _parseIconString(iconString);
    final iconName = parsed.$1;
    final detectedType = parsed.$2;

    // Use detected type if no preference specified
    final targetType = preferredType ?? detectedType;

    // Try preferred type first
    switch (targetType) {
      case IconType.flaticonRegular:
        if (_flaticonRegularMap.containsKey(iconName)) {
          return IconResult(
            type: IconType.flaticonRegular,
            data: _flaticonRegularMap[iconName]!,
            originalName: iconString,
          );
        }
        break;
      case IconType.flaticonBold:
        if (_flaticonBoldMap.containsKey(iconName)) {
          return IconResult(
            type: IconType.flaticonBold,
            data: _flaticonBoldMap[iconName]!,
            originalName: iconString,
          );
        }
        break;
      case IconType.flaticonStraight:
        if (_flaticonStraightMap.containsKey(iconName)) {
          return IconResult(
            type: IconType.flaticonStraight,
            data: _flaticonStraightMap[iconName]!,
            originalName: iconString,
          );
        }
        break;
      case IconType.fui:
        if (_fuiMap.containsKey(iconName)) {
          return IconResult(
            type: IconType.fui,
            data: _fuiMap[iconName]!,
            originalName: iconString,
          );
        }
        break;
      case IconType.material:
        break;
    }

    if (_flaticonRegularMap.containsKey(iconName)) {
      return IconResult(
        type: IconType.flaticonRegular,
        data: _flaticonRegularMap[iconName]!,
        originalName: iconString,
      );
    }
    if (_flaticonBoldMap.containsKey(iconName)) {
      return IconResult(
        type: IconType.flaticonBold,
        data: _flaticonBoldMap[iconName]!,
        originalName: iconString,
      );
    }
    if (_flaticonStraightMap.containsKey(iconName)) {
      return IconResult(
        type: IconType.flaticonStraight,
        data: _flaticonStraightMap[iconName]!,
        originalName: iconString,
      );
    }

    // Ultimate fallback
    return IconResult(
      type: IconType.material,
      data: fallback,
      originalName: iconString,
    );
  }

  /// Parse icon string and extract icon name and type
  /// Returns: (iconName, detectedType)
  static (String, IconType) _parseIconString(String iconString) {
    final normalized = iconString.toLowerCase().trim();

    // Check for Flaticon format: "fi fi-rr-phone-call"
    if (normalized.startsWith('fi ')) {
      final parts = normalized.split(' ');
      if (parts.length >= 2) {
        final stylePart = parts[1]; // "fi-rr-phone-call"

        // Detect style
        IconType type = IconType.flaticonRegular;
        if (stylePart.contains('fi-sc-')) {
          type = IconType.flaticonBold;
        } else if (stylePart.contains('fi-sr-')) {
          type = IconType.flaticonStraight;
        }

        // Extract icon name: "fi-rr-phone-call" -> "phone-call"
        final iconName = stylePart
            .replaceAll('fi-rr-', '')
            .replaceAll('fi-sc-', '')
            .replaceAll('fi-sr-', '')
            .trim();

        return (iconName, type);
      }
    }

    // Plain name
    return (normalized, IconType.material);
  }

  /// Get IconData directly (for non-FUI icons)
  static IconData getIconData(
    String iconString, {
    IconType? preferredType,
    IconData fallback = Icons.help_outline,
  }) {
    final result = convert(
      iconString,
      preferredType: preferredType,
      fallback: fallback,
    );
    return result.iconData ?? fallback;
  }

  /// Check if icon is available
  static bool isAvailable(String iconString, {IconType? specificType}) {
    final parsed = _parseIconString(iconString);
    final iconName = parsed.$1;

    if (specificType != null) {
      switch (specificType) {
        case IconType.flaticonRegular:
          return _flaticonRegularMap.containsKey(iconName);
        case IconType.flaticonBold:
          return _flaticonBoldMap.containsKey(iconName);
        case IconType.flaticonStraight:
          return _flaticonStraightMap.containsKey(iconName);
        case IconType.fui:
          return _fuiMap.containsKey(iconName);
        case IconType.material:
          return false;
      }
    }

    return _flaticonRegularMap.containsKey(iconName) ||
        _flaticonBoldMap.containsKey(iconName) ||
        _flaticonStraightMap.containsKey(iconName) ||
        _fuiMap.containsKey(iconName);
  }

  /// Get statistics
  static Map<String, int> getStats() {
    return {
      'flaticonRegular': _flaticonRegularMap.length,
      'flaticonBold': _flaticonBoldMap.length,
      'flaticonStraight': _flaticonStraightMap.length,
      'fui': _fuiMap.length,
    };
  }
}

/// Helper widget for displaying icons from string
class DynamicIcon extends StatelessWidget {
  final String iconString;
  final IconType? preferredType;
  final double? size;
  final Color? color;
  final IconData fallback;

  const DynamicIcon(
    this.iconString, {
    super.key,
    this.preferredType,
    this.size,
    this.color,
    this.fallback = Icons.help_outline,
  });

  @override
  Widget build(BuildContext context) {
    final result = IconMapper.convert(
      iconString,
      preferredType: preferredType,
      fallback: fallback,
    );

    return Icon(result.iconData, size: size, color: color);
  }
}
